# Smart Sync for Product Category
# Expected payload format:
# {
#   "name": "string",         # required - Category name (e.g., "Services", "Products")
#   "parent_name": "string"   # Parent category name (optional)
# }

if payload:
    result = model.smart_sync(payload)
    action = result
else:
    raise UserError("No payload provided in context")
